const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const DIGEST = /^[a-f0-9]{64}$/;
const PURPOSES = new Set(['information_reveal', 'plot_advance', 'conflict_escalation', 'transition', 'atmosphere', 'other']);

function fail(code, message, field) {
  return { error: { code, message, field } };
}

function parseObject(value) {
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return null; }
  }
  return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
}

function normalizedReference(value, projectId, relation) {
  if (!value || !UUID.test(value.id || value.materialId || '')) return null;
  const id = value.id || value.materialId;
  return {
    id,
    projectId,
    label: String(value.label || value.name || value.title || 'Frozen reference').slice(0, 160),
    relation: String(value.relation || relation || '').slice(0, 40),
    position: Number.isInteger(value.position) && value.position >= 0 ? value.position : 0,
    version: Number.isInteger(value.version) && value.version >= 1 ? value.version : 1,
  };
}

function fromBasePlan(base, fallback, chapterNo, additionalInstructions) {
  if (!base) return null;
  const snapshot = parseObject(base.snapshot);
  if (!snapshot) return null;
  const storylineRefs = Array.isArray(snapshot.storylineRefs)
    ? snapshot.storylineRefs.map((value) => normalizedReference(value, fallback.projectId, 'primary')).filter(Boolean)
    : [];
  if (storylineRefs.length === 0) return null;
  const materialRefs = Array.isArray(snapshot.materialRefs)
    ? snapshot.materialRefs.map((value) => normalizedReference(value, fallback.projectId, 'material_ref')).filter(Boolean)
    : [];
  const foreshadowingRefs = Array.isArray(snapshot.foreshadowingRefs)
    ? snapshot.foreshadowingRefs.map((value) => normalizedReference(value, fallback.projectId, 'foreshadowing_ref')).filter(Boolean)
    : [];
  const purpose = PURPOSES.has(snapshot.chapterPurpose) ? snapshot.chapterPurpose : 'plot_advance';
  return {
    chapterNo,
    title: typeof snapshot.title === 'string' && snapshot.title.trim() ? snapshot.title.slice(0, 120) : `Chapter ${chapterNo}`,
    summary: typeof snapshot.summary === 'string' ? snapshot.summary.slice(0, 5000) : '',
    chapterPurpose: purpose,
    storylineRefs,
    materialRefs,
    foreshadowingRefs,
    generationBasis: {
      contextSummary: snapshot.generationBasis?.contextSummary || `Deterministic reuse of frozen chapter ${chapterNo}.`,
      additionalInstructions: snapshot.generationBasis?.additionalInstructions ?? additionalInstructions ?? null,
    },
  };
}

return items.map((item) => {
  const request = item.json.body;
  if (!request || typeof request !== 'object' || Array.isArray(request)) return { json: fail('invalid_request', 'Request body must be a JSON object.', 'body') };
  const { runId, projectId, stage, input } = request;
  if (!UUID.test(runId || '')) return { json: fail('invalid_request', 'runId must be a UUID.', 'runId') };
  if (!UUID.test(projectId || '')) return { json: fail('invalid_request', 'projectId must be a UUID.', 'projectId') };
  if (stage !== 'chapter_planning') return { json: fail('invalid_request', 'stage must be chapter_planning.', 'stage') };
  if (!input || typeof input !== 'object' || Array.isArray(input)) return { json: fail('invalid_request', 'input must be the Runtime inputPayload object.', 'input') };
  const context = input.generationContext;
  const target = input.target || context?.inputSnapshot?.target;
  if (!context || typeof context !== 'object' || !target || typeof target !== 'object') return { json: fail('invalid_request', 'generationContext and target are required.', 'input') };
  if (!DIGEST.test(context.inputDigest || '')) return { json: fail('invalid_request', 'generationContext.inputDigest must be a 64-character lowercase SHA-256 digest.', 'input.generationContext.inputDigest') };
  if (!Number.isInteger(target.startChapterNo) || !Number.isInteger(target.endChapterNo) || !Number.isInteger(target.requestedChapterCount) || target.startChapterNo < 1 || target.endChapterNo < target.startChapterNo || target.requestedChapterCount !== target.endChapterNo - target.startChapterNo + 1 || target.requestedChapterCount > 100) return { json: fail('invalid_request', 'target is not a valid normalized chapter range.', 'input.target') };
  const snapshots = parseObject(context.storylineSnapshot) || {};
  const available = Array.isArray(snapshots.available) ? snapshots.available : [];
  const fallbackStoryline = normalizedReference(available[0], projectId, 'primary');
  if (!fallbackStoryline) return { json: fail('invalid_request', 'generationContext.storylineSnapshot must contain at least one frozen storyline.', 'input.generationContext.storylineSnapshot') };
  const bases = new Map((Array.isArray(context.baseChapterPlans) ? context.baseChapterPlans : []).map((base) => [base.chapterNo, base]));
  const candidates = [];
  for (let chapterNo = target.startChapterNo; chapterNo <= target.endChapterNo; chapterNo += 1) {
    const reused = fromBasePlan(bases.get(chapterNo), { projectId }, chapterNo, context.additionalInstructions);
    candidates.push(reused || {
      chapterNo,
      title: `Chapter ${chapterNo}`,
      summary: `Deterministic local chapter-planning candidate ${chapterNo}.`,
      chapterPurpose: 'plot_advance',
      storylineRefs: [fallbackStoryline],
      materialRefs: [],
      foreshadowingRefs: [],
      generationBasis: {
        contextSummary: `Deterministic local generation for chapter ${chapterNo}.`,
        additionalInstructions: context.additionalInstructions ?? null,
      },
    });
  }
  return { json: {
    projectId,
    generationMode: context.inputSnapshot?.generationMode || input.generationMode,
    target,
    sourceWorkflowRunId: runId,
    candidates,
    metadata: {
      inputDigest: context.inputDigest,
      generatedAt: '2026-01-01T00:00:00Z',
      safeProviderSummary: 'Local deterministic chapter-planning workflow; no LLM was called.',
    },
  } };
});
